<script setup lang="ts">
import type { RequestStatus } from '@/types/api';
import { requestLabel } from '@/utils/requests';
defineProps<{ status: RequestStatus }>();
const steps: RequestStatus[] = ['SUBMITTED', 'IN_REVIEW', 'APPROVED', 'READY_FOR_PICKUP', 'COMPLETED'];
</script>
<template><section aria-label="Request progress" class="space-y-3"><p v-if="status === 'REJECTED'" class="border border-red-200 bg-red-50 p-3 text-sm text-error">Rejected. Read the registrar's note below. An administrator may return the request to review.</p><ol v-else class="request-progress-list grid gap-4 sm:grid-cols-5"><li v-for="(step, index) in steps" :key="step" class="relative flex flex-col items-center gap-3 px-2 py-4 text-center text-xs" :aria-current="step === status ? 'step' : undefined"><span aria-hidden="true" class="relative z-10 flex h-10 w-10 items-center justify-center rounded-full border-2 shadow-sm" :class="index < steps.indexOf(status) ? 'border-white bg-primary-container text-white' : index === steps.indexOf(status) ? 'border-primary-container bg-white text-primary-container' : 'border-slate-200 bg-slate-50 text-slate-400'"><span class="material-symbols-outlined text-sm">{{ index < steps.indexOf(status) ? 'check' : index === steps.indexOf(status) ? 'radio_button_checked' : step === 'READY_FOR_PICKUP' ? 'location_on' : 'schedule' }}</span></span><span class="text-label-sm" :class="index <= steps.indexOf(status) ? 'text-primary' : 'text-slate-500'">{{ requestLabel(step) }}</span><span v-if="step === status" class="text-[10px] font-bold text-secondary">Current status</span></li></ol></section></template>
